package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.type.TypeBindings;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_addPropertyCreator_TriageGen0Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDescription;
    private AnnotatedWithParams creator;

    // C_PROPS is a constant used in the method, typically 0 or 1 in Jackson source.
    // Since we cannot access it directly if it's private, we assume it's handled by the logic.
    // However, the method calls verifyNonDup which is protected. 
    // In a real environment, we'd use a Spy to bypass or verify verifyNonDup.

    @Before
    public void setUp() {
        beanDescription = mock(BeanDescription.class);
        creator = mock(AnnotatedWithParams.class);
        // We use a spy to allow us to mock the protected verifyNonDup method if necessary,
        // or just to test the real implementation of addPropertyCreator.
        creatorCollector = spy(new CreatorCollector(beanDescription, true));
    }

    @Test
    public void testAddPropertyCreator_SingleProperty_Success() {
        CreatorProperty prop = mock(CreatorProperty.class);
        when(prop.getName()).thenReturn("prop1");
        CreatorProperty[] properties = new CreatorProperty[]{prop};

        creatorCollector.addPropertyCreator(creator, true, properties);

        // Verify verifyNonDup was called (assuming it's not throwing exception)
        verify(creatorCollector).addPropertyCreator(eq(creator), eq(true), any());
    }

    @Test
    public void testAddPropertyCreator_MultipleProperties_Success() {
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("name1");

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("name2");

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(creator, false, properties);
        // If no exception is thrown, it passed the duplicate check
    }

    @Test
    public void testAddPropertyCreator_DuplicateName_ThrowsException() {
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("duplicate");

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("duplicate");

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"duplicate\""));
        }
    }

    @Test
    public void testAddPropertyCreator_InjectableWithEmptyName_Skipped() {
        // Case: name is empty AND injectable value ID is not null -> Skip duplicate check
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("");
        when(prop1.getInjectableValueId()).thenReturn(new Object());

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn(new Object());

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        // This should NOT throw exception because they are skipped
        creatorCollector.addPropertyCreator(creator, true, properties);
    }

    @Test
    public void testAddPropertyCreator_EmptyNameWithoutInjectable_ThrowsException() {
        // Case: name is empty AND injectable value ID is null -> NOT skipped -> Duplicate error
        CreatorProperty prop1 = mock(CreatorProperty.class);
        when(prop1.getName()).thenReturn("");
        when(prop1.getInjectableValueId()).thenReturn(null);

        CreatorProperty prop2 = mock(CreatorProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn(null);

        CreatorProperty[] properties = new CreatorProperty[]{prop1, prop2};

        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Should have thrown IllegalArgumentException for empty names");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"\""));
        }
    }

    @Test
    public void testAddPropertyCreator_SingleProperty_NoDuplicateCheckLoop() {
        // When properties.length <= 1, the loop for duplicates is skipped
        CreatorProperty prop = mock(CreatorProperty.class);
        when(prop.getName()).thenReturn("name");
        CreatorProperty[] properties = new CreatorProperty[]{prop};

        creatorCollector.addPropertyCreator(creator, true, properties);
        // Success
    }

    @Test
    public void testAddPropertyCreator_EmptyPropertiesArray() {
        CreatorProperty[] properties = new CreatorProperty[]{};
        creatorCollector.addPropertyCreator(creator, true, properties);
        // Success
    }
}

// Mock class for CreatorProperty as it is used in the method
abstract class CreatorProperty {
    public abstract String getName();
    public abstract Object getInjectableValueId();
}
